mapper.select:
SELECT 
    o.*,
    c.customer_name as customerName
FROM opportunity o
LEFT JOIN customer c ON o.customer_id = c.customer_id
WHERE o.is_deleted = 0

    AND o.opportunity_name LIKE CONCAT('%', #{params.opportunityName}, '%')


    AND o.stage = #{params.stage}


    AND o.customer_id = #{params.customerId}


    AND o.owner_employee_id = #{params.ownerEmployeeId}


    AND o.created_at >= #{params.startDate}


    AND o.created_at <= #{params.endDate}

ORDER BY o.created_at DESC

SELECT stage as stageName, COUNT(*) as count, SUM(IFNULL(expected_amount, 0)) as totalAmount, AVG(IFNULL(probability, 0)) as avgProbability FROM opportunity WHERE is_deleted = 0
AND created_at >= #{params.startDate}
AND created_at <= #{params.endDate}
AND owner_employee_id = #{params.ownerEmployeeId}
GROUP BY stage ORDER BY CASE stage WHEN 'initial' THEN 1 WHEN 'analysis' THEN 2 WHEN 'proposal' THEN 3 WHEN 'negotiation' THEN 4 WHEN 'contract' THEN 5 WHEN 'won' THEN 6 WHEN 'lost' THEN 7 ELSE 8 END

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN stage = 'won' THEN 1 END) as wonCount, COUNT(CASE WHEN stage = 'lost' THEN 1 END) as lostCount, COUNT(CASE WHEN stage NOT IN ('won', 'lost') THEN 1 END) as activeCount, SUM(CASE WHEN stage = 'won' THEN IFNULL(expected_amount, 0) ELSE 0 END) as totalAmount, AVG(CASE WHEN stage = 'won' THEN IFNULL(expected_amount, 0) ELSE NULL END) as avgAmount FROM opportunity WHERE is_deleted = 0
AND created_at >= #{params.startDate}
AND created_at <= #{params.endDate}
AND owner_employee_id = #{params.ownerEmployeeId}

choose.when:
SELECT DATE(created_at) as date, COUNT(*) as count, SUM(IFNULL(expected_amount, 0)) as amount FROM opportunity WHERE is_deleted = 0
AND created_at >= #{params.startDate}
AND created_at <= #{params.endDate}
GROUP BY DATE(created_at) ORDER BY DATE(created_at)

SELECT YEARWEEK(created_at) as week, COUNT(*) as count, SUM(IFNULL(expected_amount, 0)) as amount FROM opportunity WHERE is_deleted = 0
AND created_at >= #{params.startDate}
AND created_at <= #{params.endDate}
GROUP BY YEARWEEK(created_at) ORDER BY YEARWEEK(created_at)

choose.otherwise:
SELECT DATE_FORMAT(created_at, '%Y-%m') as month, COUNT(*) as count, SUM(IFNULL(expected_amount, 0)) as amount FROM opportunity WHERE is_deleted = 0
AND created_at >= #{params.startDate}
AND created_at <= #{params.endDate}
GROUP BY DATE_FORMAT(created_at, '%Y-%m') ORDER BY DATE_FORMAT(created_at, '%Y-%m')
